"use client";

import { Thinking } from "./thinking";
import { Streaming } from "./streaming";
import { ToolCall, type ToolStep } from "./tool-call";
import { Stalled } from "./stalled";
import { ErrorState } from "./error-state";
import { Done } from "./done";
import {
  cx,
  type AgentStatus,
  type AgentStatusSnapshot,
  type WaitStateProps,
} from "./types";

export type AgentStateProps = WaitStateProps & {
  status: AgentStatus | AgentStatusSnapshot;
  text?: string;
  toolName?: string;
  steps?: ToolStep[];
  errorMessage?: string;
  onRetry?: () => void;
  onCancel?: () => void;
};

function isSnapshot(value: AgentStatus | AgentStatusSnapshot): value is AgentStatusSnapshot {
  return typeof value === "object";
}

export function AgentState({
  status,
  className,
  duotone = false,
  text,
  toolName,
  steps,
  errorMessage,
  onRetry,
  onCancel,
}: AgentStateProps) {
  const snapshot = isSnapshot(status) ? status : undefined;
  const state: AgentStatus = snapshot ? snapshot.state : (status as AgentStatus);
  const cancel = onCancel ?? snapshot?.cancel;

  return (
    <div
      key={state}
      className={cx(
        "crate-state-in motion-reduce:opacity-100",
        className,
      )}
      aria-live="polite"
      aria-atomic="true"
    >
      {state === "thinking" ? (
        <Thinking
          duotone={duotone}
          elapsedMs={snapshot?.elapsedMs}
          label={snapshot?.label === "Thinking…" ? undefined : snapshot?.label}
          onCancel={cancel}
        />
      ) : null}
      {state === "tool" ? (
        <ToolCall
          duotone={duotone}
          toolName={toolName ?? snapshot?.activeToolName}
          steps={steps}
        />
      ) : null}
      {state === "streaming" ? <Streaming duotone={duotone} text={text} /> : null}
      {state === "stalled" ? <Stalled duotone={duotone} /> : null}
      {state === "error" ? <ErrorState message={errorMessage} onRetry={onRetry} /> : null}
      {state === "done" ? <Done duotone={duotone} /> : null}
      <style>{`@media (prefers-reduced-motion: no-preference) { @keyframes crate-state-enter { from { opacity: 0; transform: translateY(4px) } to { opacity: 1; transform: none } } .crate-state-in { animation: crate-state-enter 260ms ease-out both; } }`}</style>
    </div>
  );
}

import { cx, duoBackground, type WaitStateProps } from "./types";

export type ThinkingProps = WaitStateProps & {
  elapsedMs?: number;
  onCancel?: () => void;
  label?: string;
};

export function Thinking({
  className,
  duotone = false,
  elapsedMs = 0,
  onCancel,
  label,
}: ThinkingProps) {
  const message = label ?? (elapsedMs >= 8000 ? "Still thinking…" : "Thinking…");
  const visibleLabel = elapsedMs >= 2000 || Boolean(label);
  const canCancel = elapsedMs >= 20000 && Boolean(onCancel);

  return (
    <div
      className={cx(
        "inline-flex min-h-10 items-center gap-3 rounded-[16px] border border-border bg-background px-4 py-2.5 text-sm text-muted-foreground shadow-[0_12px_30px_-20px_color-mix(in_srgb,var(--primary)_35%,transparent)]",
        className,
      )}
      aria-live="polite"
      aria-label={message}
    >
      <span className="flex items-center gap-1.5" aria-hidden="true">
        {[0, 1, 2].map((index) => (
          <span
            key={index}
            className="size-1.5 rounded-full bg-primary motion-safe:animate-bounce motion-reduce:opacity-70"
            style={{
              animationDelay: `${index * 140}ms`,
              background: duotone ? duoBackground : undefined,
            }}
          />
        ))}
      </span>
      {visibleLabel ? <span>{message}</span> : <span className="sr-only">{message}</span>}
      {canCancel ? (
        <button
          type="button"
          onClick={onCancel}
          className="ml-1 rounded-lg border border-border px-2.5 py-1 text-xs font-medium text-foreground transition-colors hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
        >
          Cancel
        </button>
      ) : null}
    </div>
  );
}

import { cx, duoBackground, type WaitStateProps } from "./types";

export type StreamingProps = WaitStateProps & {
  children?: React.ReactNode;
  text?: string;
};

export function Streaming({ className, duotone = false, children, text }: StreamingProps) {
  return (
    <span
      className={cx("text-sm leading-7 text-foreground", className)}
      aria-live="polite"
      aria-label="Response streaming"
    >
      {children ?? text}
      <span
        aria-hidden="true"
        className="ml-1 inline-block h-[1.05em] w-[3px] translate-y-[2px] rounded-full bg-primary shadow-[0_0_12px_color-mix(in_srgb,var(--primary)_60%,transparent)] motion-safe:animate-pulse motion-reduce:opacity-80"
        style={{ background: duotone ? duoBackground : undefined }}
      />
    </span>
  );
}

import { Check, Circle, LoaderCircle, Search, FileText, Wrench } from "lucide-react";
import { cx, duoBackground, type WaitStateProps } from "./types";

export type ToolStep = {
  id?: string;
  label: string;
  toolName?: string;
  state?: "pending" | "active" | "complete";
};

export type ToolCallProps = WaitStateProps & {
  steps?: ToolStep[];
  toolName?: string;
  label?: string;
};

function ToolIcon({ name, active }: { name?: string; active: boolean }) {
  const iconClass = "size-3.5";
  if (active) return <LoaderCircle className={cx(iconClass, "motion-safe:animate-spin")} />;
  if (name?.toLowerCase().includes("search")) return <Search className={iconClass} />;
  if (name?.toLowerCase().includes("file") || name?.toLowerCase().includes("read")) {
    return <FileText className={iconClass} />;
  }
  return <Wrench className={iconClass} />;
}

export function ToolCall({
  className,
  duotone = false,
  steps,
  toolName = "tool",
  label,
}: ToolCallProps) {
  const items = steps?.length
    ? steps
    : [{ label: label ?? `Running ${toolName}…`, toolName, state: "active" as const }];

  return (
    <div
      className={cx(
        "w-full max-w-sm rounded-[16px] border border-border bg-background p-2 shadow-[0_14px_34px_-24px_color-mix(in_srgb,var(--primary)_35%,transparent)]",
        className,
      )}
      aria-live="polite"
      aria-label="Agent tool activity"
    >
      <ol className="space-y-1">
        {items.map((step, index) => {
          const state = step.state ?? (index === items.length - 1 ? "active" : "complete");
          return (
            <li
              key={step.id ?? `${step.label}-${index}`}
              className={cx(
                "flex items-center gap-2.5 rounded-xl px-3 py-2 text-sm",
                state === "active" ? "bg-muted text-foreground" : "text-muted-foreground",
              )}
            >
              <span
                className={cx(
                  "grid size-6 shrink-0 place-items-center rounded-lg border border-border bg-background text-muted-foreground",
                  state === "active" && "text-primary",
                )}
                style={state === "active" && duotone ? { background: duoBackground, color: "white" } : undefined}
                aria-hidden="true"
              >
                {state === "complete" ? (
                  <Check className="size-3.5" />
                ) : state === "pending" ? (
                  <Circle className="size-3" />
                ) : (
                  <ToolIcon name={step.toolName} active />
                )}
              </span>
              <span>{step.label}</span>
            </li>
          );
        })}
      </ol>
    </div>
  );
}

import { Clock3 } from "lucide-react";
import { cx, duoBackground, type WaitStateProps } from "./types";

export type StalledProps = WaitStateProps & { message?: string };

export function Stalled({ className, duotone = false, message = "Still working…" }: StalledProps) {
  return (
    <div
      className={cx(
        "inline-flex items-center gap-2.5 rounded-[16px] border border-border bg-background px-4 py-2.5 text-sm text-muted-foreground shadow-[0_12px_30px_-22px_color-mix(in_srgb,var(--primary)_40%,transparent)]",
        className,
      )}
      aria-live="polite"
    >
      <span
        className="grid size-6 place-items-center rounded-lg bg-muted text-primary motion-safe:animate-pulse motion-reduce:opacity-80"
        style={duotone ? { background: duoBackground, color: "white" } : undefined}
        aria-hidden="true"
      >
        <Clock3 className="size-3.5" />
      </span>
      {message}
    </div>
  );
}

import { AlertCircle, RotateCcw } from "lucide-react";
import { cx, type WaitStateProps } from "./types";

export type ErrorStateProps = WaitStateProps & {
  message?: string;
  onRetry?: () => void;
};

export function ErrorState({
  className,
  message = "Something went wrong.",
  onRetry,
}: ErrorStateProps) {
  return (
    <div
      className={cx(
        "flex w-full max-w-sm items-center gap-3 rounded-[16px] border border-border bg-background p-3 text-sm shadow-[0_12px_30px_-22px_color-mix(in_srgb,var(--primary)_35%,transparent)]",
        className,
      )}
      role="status"
      aria-live="polite"
    >
      <AlertCircle className="size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
      <span className="min-w-0 flex-1 text-foreground">{message}</span>
      {onRetry ? (
        <button
          type="button"
          onClick={onRetry}
          className="inline-flex items-center gap-1.5 rounded-lg border border-border px-2.5 py-1.5 text-xs font-medium text-foreground transition-colors hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
        >
          <RotateCcw className="size-3" aria-hidden="true" /> Retry
        </button>
      ) : null}
    </div>
  );
}

export { ErrorState as Error };

import { Check } from "lucide-react";
import { cx, duoBackground, type WaitStateProps } from "./types";

export type DoneProps = WaitStateProps & { label?: string };

export function Done({ className, duotone = false, label = "Done" }: DoneProps) {
  return (
    <span
      className={cx(
        "crate-done inline-flex items-center gap-2 text-sm text-muted-foreground motion-reduce:opacity-70",
        className,
      )}
      aria-live="polite"
    >
      <span
        className="grid size-6 place-items-center rounded-full bg-muted text-primary"
        style={duotone ? { background: duoBackground, color: "white" } : undefined}
        aria-hidden="true"
      >
        <Check className="size-3.5" strokeWidth={2.5} />
      </span>
      {label}
      <style>{`@media (prefers-reduced-motion: no-preference) { @keyframes crate-done-fade { 0% { opacity: 0 } 18%, 72% { opacity: 1 } 100% { opacity: .25 } } .crate-done { animation: crate-done-fade 2.4s ease both; } }`}</style>
    </span>
  );
}

export type AgentStatus =
  | "thinking"
  | "tool"
  | "streaming"
  | "stalled"
  | "error"
  | "done";

export type AgentStatusSnapshot = {
  state: AgentStatus;
  activeToolName?: string;
  elapsedMs: number;
  showCancel: boolean;
  label: string;
  cancel?: () => void;
};

export type WaitStateProps = {
  className?: string;
  duotone?: boolean;
};

export function cx(...values: Array<string | false | null | undefined>) {
  return values.filter(Boolean).join(" ");
}

export const duoBackground =
  "linear-gradient(120deg, #9E8CF2 0%, #6FB6F0 100%)";

export { AgentState, type AgentStateProps } from "./agent-state";
export { Thinking, type ThinkingProps } from "./thinking";
export { Streaming, type StreamingProps } from "./streaming";
export { ToolCall, type ToolCallProps, type ToolStep } from "./tool-call";
export { Stalled, type StalledProps } from "./stalled";
export { Error, ErrorState, type ErrorStateProps } from "./error-state";
export { Done, type DoneProps } from "./done";
export type { AgentStatus, AgentStatusSnapshot, WaitStateProps } from "./types";

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type { AgentStatus, AgentStatusSnapshot } from "@/components/agent-wait-states/types";

type UnknownPart = {
  type?: string;
  text?: string;
  state?: string;
  toolName?: string;
  toolInvocation?: {
    toolName?: string;
    state?: string;
  };
};

type ChatLike = {
  status: "submitted" | "streaming" | "ready" | "error" | string;
  messages: Array<{
    role?: string;
    parts?: UnknownPart[];
    content?: string;
  }>;
  error?: unknown;
  stop?: () => void;
};

export type UseAgentStatusOptions = {
  manualStatus?: AgentStatus;
  onCancel?: () => void;
  stallAfterMs?: number;
};

const FINISHED_TOOL_STATES = new Set([
  "output-available",
  "output-error",
  "result",
  "error",
]);

function readTool(part: UnknownPart) {
  const type = part.type ?? "";
  const invocation = part.toolInvocation;
  const name =
    part.toolName ??
    invocation?.toolName ??
    (type.startsWith("tool-") ? type.slice(5) : undefined);
  const state = part.state ?? invocation?.state;
  const isTool = type === "dynamic-tool" || type === "tool-invocation" || type.startsWith("tool-");
  return isTool && name && !FINISHED_TOOL_STATES.has(state ?? "") ? name : undefined;
}

function inspectMessages(messages: ChatLike["messages"]) {
  let activeToolName: string | undefined;
  let content = "";

  for (const message of messages) {
    if (message.content) content += message.content;
    for (const part of message.parts ?? []) {
      if (part.type === "text" && part.text) content += part.text;
      const toolName = readTool(part);
      if (toolName) activeToolName = toolName;
    }
  }

  return { activeToolName, contentSignature: `${content.length}:${content.slice(-80)}` };
}

export function useAgentStatus(
  chat: ChatLike,
  options: UseAgentStatusOptions = {},
): AgentStatusSnapshot {
  const { activeToolName, contentSignature } = useMemo(
    () => inspectMessages(chat.messages),
    [chat.messages],
  );
  const [now, setNow] = useState(() => Date.now());
  const busySince = useRef<number | null>(null);
  const lastContentAt = useRef(Date.now());
  const previousSignature = useRef(contentSignature);
  const wasBusy = useRef(false);

  const busy = chat.status === "submitted" || chat.status === "streaming";

  useEffect(() => {
    if (busy && busySince.current === null) busySince.current = Date.now();
    if (!busy) busySince.current = null;
    if (busy) wasBusy.current = true;
  }, [busy]);

  useEffect(() => {
    if (contentSignature !== previousSignature.current) {
      previousSignature.current = contentSignature;
      lastContentAt.current = Date.now();
      setNow(Date.now());
    }
  }, [contentSignature]);

  useEffect(() => {
    if (!busy) return;
    const timer = window.setInterval(() => setNow(Date.now()), 250);
    return () => window.clearInterval(timer);
  }, [busy]);

  const elapsedMs = busySince.current ? Math.max(0, now - busySince.current) : 0;
  const stalled =
    chat.status === "streaming" && now - lastContentAt.current >= (options.stallAfterMs ?? 5000);

  let state: AgentStatus;
  if (options.manualStatus) state = options.manualStatus;
  else if (chat.status === "error" || chat.error) state = "error";
  else if (stalled) state = "stalled";
  else if (activeToolName && busy) state = "tool";
  else if (chat.status === "streaming") state = "streaming";
  else if (chat.status === "submitted") state = "thinking";
  else state = "done";

  const label = elapsedMs >= 8000 ? "Still thinking…" : "Thinking…";
  const cancel = options.onCancel ?? chat.stop;

  return {
    state,
    activeToolName,
    elapsedMs,
    showCancel: elapsedMs >= 20000 && Boolean(cancel),
    label,
    cancel,
  };
}
